    Arrays.fill(ans, -1);
    Map<Integer, Integer> slot = new HashMap<>();   // value -> its index in nums1
    for (int i = 0; i < nums1.length; i++) slot.put(nums1[i], i);
    Deque<Integer> waiting = new ArrayDeque<>();    // still looking for something bigger
    for (int x : nums2) {
        while (!waiting.isEmpty() && waiting.peek() < x) {
            int y = waiting.pop();                  // x is y's next greater element
