vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
    vector<int> ans(nums1.size(), -1);
    unordered_map<int, int> slot;           // value -> its index in nums1
    for (int i = 0; i < (int)nums1.size(); i++) slot[nums1[i]] = i;
    stack<int> waiting;                     // still looking for something bigger
    for (int x : nums2) {
        while (!waiting.empty() && waiting.top() < x) {
            int y = waiting.top();          // x is y's next greater element
            waiting.pop();
            auto it = slot.find(y);
            if (it != slot.end()) ans[it->second] = x;
        }
        waiting.push(x);
    }
    return ans;
}
